      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" fill=\"#ffd700\" font-size=\"36\" font-family=\"Arial\" text-anchor=\"middle\" font-weight=\"bold\">Skeleton as Record</text><text x=\"550\" y=\"115\" fill=\"#888\" font-size=\"24\" font-family=\"Arial\" text-anchor=\"middle\">Bone responds to use</text><rect x=\"100\" y=\"280\" width=\"900\" height=\"380\" fill=\"#2a2a4e\" stroke=\"#ffd700\" stroke-width=\"4\" rx=\"20\"/><text x=\"550\" y=\"360\" fill=\"#ffd700\" font-size=\"30\" font-family=\"Arial\" text-anchor=\"middle\" font-style=\"italic\">\"The skeleton</text><text x=\"550\" y=\"405\" fill=\"#ffd700\" font-size=\"30\" font-family=\"Arial\" text-anchor=\"middle\" font-style=\"italic\">is not destiny.</text><text x=\"550\" y=\"490\" fill=\"#ec4899\" font-size=\"30\" font-family=\"Arial\" text-anchor=\"middle\" font-style=\"italic\">It is a record of</text><text x=\"550\" y=\"535\" fill=\"#10b981\" font-size=\"34\" font-family=\"Arial\" text-anchor=\"middle\" font-style=\"italic\" font-weight=\"bold\">how we have used it.\"</text><text x=\"550\" y=\"600\" fill=\"#888\" font-size=\"22\" font-family=\"Arial\" text-anchor=\"middle\">- paraphrased from Nestor</text><rect x=\"100\" y=\"700\" width=\"900\" height=\"280\" fill=\"#2a2a4e\" stroke=\"#6366f1\" stroke-width=\"3\" rx=\"15\"/><text x=\"550\" y=\"750\" fill=\"#6366f1\" font-size=\"26\" font-family=\"Arial\" text-anchor=\"middle\" font-weight=\"bold\">What we've covered</text><text x=\"550\" y=\"800\" fill=\"#ffffff\" font-size=\"22\" font-family=\"Arial\" text-anchor=\"middle\">L1 Lost art - L2 Nose - L3 Slow - L4 CO2</text><text x=\"550\" y=\"845\" fill=\"#ffffff\" font-size=\"22\" font-family=\"Arial\" text-anchor=\"middle\">L5 Sleep - L6 Heavy breath - L7 Face/posture</text><text x=\"550\" y=\"920\" fill=\"#ffd700\" font-size=\"26\" font-family=\"Arial\" text-anchor=\"middle\" font-weight=\"bold\">Next: Lesson 8 - your daily protocol</text></svg>",
